package jp.personal.hanshinedge.ui;
import android.app.Activity;import android.webkit.WebView;import android.webkit.WebViewClient;import org.json.*;import java.util.*;import java.util.concurrent.*;import java.net.*;import java.io.*;import java.nio.charset.*;import java.security.*;import java.time.*;import java.util.regex.*;import jp.personal.hanshinedge.runtime.*;import jp.personal.hanshinedge.prediction.*;
public final class RaceRepository implements AutoCloseable {
 public interface Callback {void done(JSONObject value,String error);}
 private final Activity activity;private final WebView parser;private final ExecutorService io=Executors.newSingleThreadExecutor();private volatile boolean closed=false;private boolean ready=false;private final List<Runnable> waiting=new ArrayList<>();private final jp.personal.hanshinedge.prospective.ProspectiveRuntime prospective;
 public static final String[] JP={"札幌","函館","福島","新潟","東京","中山","中京","京都","阪神","小倉"},EN={"SAPPORO","HAKODATE","FUKUSHIMA","NIIGATA","TOKYO","NAKAYAMA","CHUKYO","KYOTO","HANSHIN","KOKURA"};
 public RaceRepository(Activity a){activity=a;prospective=new jp.personal.hanshinedge.prospective.ProspectiveRuntime(a,"jra-ui");io.execute(()->{try{jp.personal.hanshinedge.prospective.BackgroundScheduler.resume(a.getApplicationContext(),"jra-ui");}catch(Exception ignored){}});parser=new WebView(a);parser.getSettings().setJavaScriptEnabled(true);parser.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView w,String u){ready=true;for(Runnable r:new ArrayList<>(waiting))r.run();waiting.clear();}});parser.loadData("<!doctype html><title>Local inert parser</title>","text/html","UTF-8");}
 public static String asset(Activity a,String name)throws Exception{try(InputStream in=a.getAssets().open(name);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}}
 public JSONArray historical()throws Exception{return new JSONObject(asset(activity,"jra-real-historical-fixture-20260919-20261114.json")).getJSONArray("races");}
 private void parse(String html,JSONObject meeting,Callback cb){if(closed)return;try{String script=asset(activity,"catalog_parser.js")+"("+JSONObject.quote(html)+","+(meeting==null?"null":meeting.toString())+")";Runnable r=()->parser.evaluateJavascript(script,s->{if(closed)return;try{JSONObject value=new JSONObject(s);cb.done(value,value.optString("error",null));}catch(Exception e){cb.done(null,"PARSER_RESULT_INVALID");}});if(ready)r.run();else waiting.add(r);}catch(Exception e){cb.done(null,e.toString());}}
 private void fetch(String cname,java.util.function.BiConsumer<String,JSONObject> ok,Callback cb){if(closed)return;io.execute(()->{try{jp.personal.hanshinedge.prospective.JraSource.Page page=jp.personal.hanshinedge.prospective.JraSource.fetch("D",cname);activity.runOnUiThread(()->{if(!closed)ok.accept(page.html,page.receipt);});}catch(Exception e){activity.runOnUiThread(()->{if(!closed)cb.done(null,"SOURCE_UNAVAILABLE: "+e.getMessage());});}});}

 public void today(Callback cb){fetch("pw01dli00/F3",(h,proof)->parse(h,null,(value,error)->{if(error!=null){cb.done(null,error);return;}try{JSONArray all=value.getJSONArray("meetings"),today=new JSONArray();String date=LocalDate.now(ZoneId.of("Asia/Tokyo")).toString();for(int i=0;i<all.length();i++){JSONObject m=all.getJSONObject(i);int code=Integer.parseInt(m.getString("venue_code"));if(date.equals(m.getString("date"))&&code>=1&&code<=10){m.put("venue",JP[code-1]).put("venue_enum",EN[code-1]);today.put(m);}}cb.done(new JSONObject().put("meetings",today),null);}catch(Exception e){cb.done(null,e.toString());}}),cb);}
 public void races(JSONObject meeting,Callback cb){fetch(meeting.optString("cname"),(html,receipt)->{Matcher m=Pattern.compile("pw01des(?:01|10)"+meeting.optString("venue_code")+meeting.optString("date").substring(0,4)+String.format(java.util.Locale.ROOT,"%02d%02d",meeting.optInt("meeting"),meeting.optInt("day"))+meeting.optString("date").replace("-","")+"/[A-Za-z0-9]{2}").matcher(html);if(!m.find()){cb.done(null,"CATALOG_LINK_NOT_OBSERVED");return;}String token=m.group();fetch(token,(card,proof)->parse(card,meeting,(v,e)->{if(e!=null||v==null){cb.done(v,e);return;}io.execute(()->{try{v.put("receipt",proof);JSONArray races=v.getJSONArray("races");for(int i=0;i<races.length();i++){JSONObject race=races.getJSONObject(i),reg=prospective.register(race,proof,System.currentTimeMillis(),android.os.SystemClock.elapsedRealtime());race.put("REAL_PROSPECTIVE",reg.getBoolean("REAL_PROSPECTIVE")).put("registration_reason",reg.getString("reason")).put("registered_at",reg.getString("registered_at")).put("clock_receipt",reg.getJSONObject("clock")).put("source_receipt",proof);if(reg.getBoolean("REAL_PROSPECTIVE")){jp.personal.hanshinedge.prospective.BackgroundScheduler.schedule(activity.getApplicationContext(),"jra-ui",reg);prospective.shadow(reg.getString("race_id"));}}activity.runOnUiThread(()->{if(!closed)cb.done(v,null);});}catch(Exception ex){activity.runOnUiThread(()->{if(!closed)cb.done(null,ex.getMessage());});}});}),cb);},cb);}
 public CapabilityGate.RaceContext context(JSONObject r)throws Exception{int code=Integer.parseInt(r.getString("venue_code"));String id=r.optString("race_id","");if(id.isEmpty()||id.equals("null"))throw new IllegalArgumentException("RACE_ID_UNRESOLVED");return new CapabilityGate.RaceContext(id,EN[code-1],r.getInt("race_no"),r.optBoolean("obstacle"),r.optBoolean("REAL_PROSPECTIVE",false),(prospective.resultKnown(id)||r.optBoolean("result_known",r.optString("data_status").equals("HISTORICAL_REPLAY_ONLY"))),CapabilityGate.FROZEN_MODEL);}
 public PredictionProvider.Prediction prediction(JSONObject r)throws Exception{if(!r.optString("data_status").equals("TEST_ONLY")&&jp.personal.hanshinedge.runtime.CapabilityGate.evaluate(context(r)).formalPaperBuy){JSONObject clock=jp.personal.hanshinedge.prospective.ProspectiveRuntime.clock(r.optJSONObject("source_receipt")==null?new JSONObject():r.getJSONObject("source_receipt"),System.currentTimeMillis(),android.os.SystemClock.elapsedRealtime());if(!clock.getBoolean("verified")){PredictionProvider.Prediction p=new PredictionProvider.Prediction();p.reason="CLOCK_UNVERIFIED";p.capabilityAction="BLOCKED";return p;}}List<FrozenMf0Engine.Input> inputs=new ArrayList<>();JSONArray runners=r.optJSONArray("runners");if(runners!=null)for(int i=0;i<runners.length();i++){JSONObject x=runners.getJSONObject(i);Double f=x.has("f0")&&!x.isNull("f0")?x.getDouble("f0"):null;Double odds=x.has("win_odds")&&!x.isNull("win_odds")?x.getDouble("win_odds"):null;inputs.add(new FrozenMf0Engine.Input(x.getInt("horse_no"),x.optString("horse_name"),odds,f));}return new PredictionProvider().predict(context(r),inputs,r.has("odds_retrieved_at")?r.getLong("odds_retrieved_at"):null,System.currentTimeMillis());}
 public JSONObject paper()throws Exception{return prospective.bankroll().put("background",jp.personal.hanshinedge.prospective.BackgroundScheduler.status(activity.getApplicationContext()));}
 public JSONArray timechain(JSONObject r)throws Exception{JSONArray all=prospective.rows("TIMECHAIN"),out=new JSONArray();for(int i=0;i<all.length();i++){JSONObject p=new JSONObject(all.getJSONObject(i).getString("payload"));if(r.optString("race_id").equals(p.optString("race_id")))out.put(p);}return out;}
 public JSONArray results(JSONObject r)throws Exception{JSONArray all=prospective.rows("RESULT"),out=new JSONArray();for(int i=0;i<all.length();i++){JSONObject p=new JSONObject(all.getJSONObject(i).getString("payload"));if(r.optString("race_id").equals(p.optString("race_id")))out.put(p);}return out;}

 @Override public void close(){closed=true;io.shutdownNow();parser.destroy();prospective.close();}
}
